contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Run tries to withdraw _am from c. It is payable to fund deposits if needed.
    function run(uint depositAmount, uint _am) public payable {
        require(address(this).balance >= depositAmount);

        // Clean precondition: ensure we have some funds externally to send when depositing
        // Deposit depositAmount into c (only if >= MinDeposit else Deposit will ignore)
        if (depositAmount > 0) {
            c.Deposit{value: depositAmount}();
        }

        // Read balances before cashout
        uint beforeContractBalance = address(c).balance;
        uint beforeRecorded = c.balances(address(this));

        // Try CashOut and capture whether it reverted
        bool reverted;
        try c.CashOut(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterContractBalance = address(c).balance;
        uint afterRecorded = c.balances(address(this));

        // Assert general invariant:
        // 1) The recorded balance in c for this test contract never increases.
        // 2) If CashOut did not revert, then recorded decreases by exactly the funds sent (and contract balance decreased by same amount).
        // 3) If it reverted, both recorded and contract balance remain the same.
        assert(
            // recorded never increases
            afterRecorded <= beforeRecorded
            && (
                // case: reverted -> both unchanged
                (reverted && afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance)
                // case: not reverted -> recorded decreased by exactly _am and contract balance decreased by exactly _am
                || (!reverted && (beforeRecorded - afterRecorded == _am) && (beforeContractBalance - afterContractBalance == _am))
            )
        );
    }

    // Allow receiving Ether when c sends funds back to this contract
    receive() external payable {}
}

