contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: deposit some amount (>= MinDeposit) then attempt CashOut of some amount
    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(depositAmount >= 1 ether);
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= depositAmount);

        // read initial observed values
        uint beforeContractBalance = address(c).balance;
        uint beforeRecorded = c.balances(address(this));

        // Perform a Deposit into c from this contract
        c.Deposit{value: depositAmount}();

        // read after deposit
        uint afterRecorded = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // Sanity: deposit should increase recorded by either 0 (if depositAmount < MinDeposit) or by depositAmount
        // but since we required depositAmount >= MinDeposit, it must increase by depositAmount
        // Now attempt CashOut of cashOutAmount and record whether it reverted
        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalRecorded = c.balances(address(this));
        uint finalContractBalance = address(c).balance;

        // General property to assert for ALL inputs:
        // If CashOut did NOT revert, then the recorded balance must have decreased by exactly cashOutAmount
        // and the contract's Ether balance must have decreased by at least cashOutAmount.
        // If CashOut reverted, recorded balance must be unchanged.
        assert(
            (!reverted && (beforeRecorded + (afterRecorded - beforeRecorded) - finalRecorded == cashOutAmount) && (afterContractBalance - finalContractBalance >= cashOutAmount))
            || (reverted && finalRecorded == afterRecorded)
        );
    }

    // allow receiving ETH for funding deposits
    receive() external payable {}
}

