    // depositAmount must be at least MinDeposit to ensure Deposit actually updates balances
    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(depositAmount >= 1 ether);
        require(address(this).balance >= depositAmount);

        // read before-values
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // perform a Deposit from this contract into c
        c.Deposit{value: depositAmount}();

        // read recorded and contract balance after deposit
        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // attempt CashOut and capture whether it reverted
        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalRecorded = c.balances(address(this));
        uint finalContractBal = address(c).balance;

        // General property:
        // - If CashOut did not revert then finalRecorded == afterRecorded - cashOutAmount
        //   and afterContractBal - finalContractBal == cashOutAmount.
        // - If CashOut reverted then finalRecorded == afterRecorded and finalContractBal == afterContractBal.
        assert(
            (!reverted && afterRecorded >= cashOutAmount && finalRecorded == (afterRecorded - cashOutAmount) && afterContractBal >= finalContractBal && (afterContractBal - finalContractBal) == cashOutAmount)
            || (reverted && finalRecorded == afterRecorded && finalContractBal == afterContractBal)
        );
    }

